package br.com.cineo;
import org.json.*;import android.os.SystemClock;
/** Each playback owns its state so a pending final heartbeat can survive an episode swipe. */
class QualifiedPlayback {
 final MainActivity a;Session current;QualifiedPlayback(MainActivity activity){a=activity;}
 static class Session{final int page,episode;final String account,viewer,source;String id="";long tick,last,played;int position;boolean pending,finishing,finalSent,excluded;Session(int p,int e,String u,String v,String origin){page=p;episode=e;account=u;viewer=v;source=origin;tick=SystemClock.elapsedRealtime();}}
 void setup(){current=null;if(!a.drama.publicEpisode()||a.token.isEmpty()||a.uid.equals(a.activeShow.optString("owner_id")))return;current=new Session(a.generation,a.playingEpisode,a.uid,a.viewerToken,a.activeShow.optString("_source","home"));}
 void tick(){Session s=current;if(s==null||s.page!=a.generation||a.video==null)return;long now=SystemClock.elapsedRealtime();boolean submit=false;synchronized(s){long delta=Math.max(0,Math.min(1000,now-s.tick));s.tick=now;if(s.excluded||s.finishing||!a.video.isPlaying()||a.scrubbing)return;s.played=Math.min(14400000,s.played+delta);s.position=a.video.getCurrentPosition();if(!s.pending&&now-s.last>=5000){s.last=now;submit=true;}}if(submit)send(s);}
 void finish(){Session s=current;if(s==null||a.video==null)return;synchronized(s){if(s.finishing||s.excluded)return;if(a.video.isPlaying()&&!a.scrubbing)s.played=Math.min(14400000,s.played+Math.max(0,Math.min(1000,SystemClock.elapsedRealtime()-s.tick)));s.position=a.video.getCurrentPosition();s.finishing=true;}send(s);}
 void send(Session s){final boolean start;final String session;final int position,active;synchronized(s){if(s.pending||s.excluded||s.finalSent)return;s.pending=true;session=s.id;start=session.isEmpty();position=s.position;active=(int)s.played;if(!start&&s.finishing)s.finalSent=true;}a.reads.execute(()->{boolean drain=false;try{a.requestViewer.set(s.viewer);a.readFlow.ensureSession(s.account);JSONObject response=a.request("POST",start?"/v10/view/start":"/v10/view/heartbeat",start?a.obj("episode_id",s.episode,"position_ms",position,"active_ms",active,"source",s.source):a.obj("id",session,"position_ms",position,"active_ms",active),a.token);synchronized(s){if(start){s.id=response.optString("id");s.excluded=response.optBoolean("excluded")||s.id.isEmpty();}s.pending=false;drain=s.finishing&&!s.finalSent&&!s.excluded&&!s.id.isEmpty();}}catch(Exception ignored){synchronized(s){s.pending=false;}}finally{a.requestViewer.remove();}if(drain)send(s);});}
}
